-- Multi-Angle Research fixes after suite20 (MULTI_ANGLE_FIX_PLAN.md items 1, 2, 4 and 5; 2026-09-29): Tool_Catalog
-- registrations of the changed market-ai-orc tools. No table or column changes.
--
-- check_research_feasibility v2: each angle carries its design (M38), checked before a plan is written.
-- run_research_code v2: the forward return may read the price of another request of the angle (S15).
-- complete_research_run v2: the first finalize while an approved angle is unrecorded is answered with what is missing
-- (M36).
-- get_research_library v1: the eight methods from public."AI_research_library" (C07; migration 20260930_001).
-- Generated from the market-ai-orc tool definitions (tests/test_multi_angle.py fails when they drift); inactive like
-- every other market-ai-orc row (market-ai-orc registers its tools in code). The v1 rows stay as history; each v2 row
-- copies its v1 row's limits and adds what changed. The latest version is read with
-- ORDER BY length(version) DESC, version DESC.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('check_research_feasibility', 'v2'), ('run_research_code', 'v2'), ('complete_research_run', 'v2'), ('get_research_library', 'v1'))) THEN
        RAISE EXCEPTION 'The multi-angle fix tool versions are already registered';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE version = 'v1'
          AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND tool_name IN ('check_research_feasibility', 'run_research_code', 'complete_research_run')) <> 3 THEN
        RAISE EXCEPTION 'The v1 multi-angle research tools (migration 20260929_001) are required';
    END IF;
    IF to_regclass('public."AI_research_library"') IS NULL THEN
        RAISE EXCEPTION 'AI_research_library (migration 20260930_001) is required';
    END IF;
END;
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT v1.tool_name, v1.tool_family, v1.tool_type,
       'Before presenting a multi-angle Research Plan, check every angle''s design and data. Send one entry per planned angle: angle_id, its design (method from get_research_library, parameters, horizon, unit, comparisons, multiple-testing policy, holdout, and for a forward-return outcome the request and price column) and its DataNeedSpec v2 data_requests and relationships in the angle''s own ids. The backend checks each design against the method''s rules and data requirements, merges equal requests of different angles into one bundle when they fit, splits the angles into a few bundle groups only when they do not, validates each group and estimates its extraction without reading data. Returns FEASIBLE with the bundle groups, each angle''s bundle request and range ids and the columns it may use (its data contract); NOT_FEASIBLE naming the angles that cannot be served; or REVISION_REQUIRED with issues by angle. Present the plan only after FEASIBLE, with exactly the angles and designs checked.',
