       v1.max_input_rows, v1.max_tickers, v1.max_date_range_days, v1.max_estimated_rows,
       v1.timeout_seconds, v1.max_output_bytes, v1.max_llm_result_rows,
       v1.max_llm_result_bytes, v1.max_llm_result_tokens,
       v1.requires_analytics_worker, v1.requires_feature_catalog, v1.requires_data_readiness,
       v1.tool_specific_limits || '{"data_plan_design_binding":"angle_design_sha256s; the plan gate compares every plan angle''s design with it (PLAN_FEASIBILITY, then PLAN_FEASIBILITY_2)","design_check":"M38 (2026-09-29): each angle''s design is checked against the rules the final plan enforces and the research library''s data requirements; metadata only, no data read before approval","design_codes":["DESIGN_PARAMETERS","MULTIPLE_TESTING_POLICY_REQUIRED","HOLDOUT_NEEDS_TWO_RANGES","ENTITY_COLUMN_REQUIRED","OUTCOME_PRICE_REQUIRED","OUTCOME_PRICE_REQUEST_UNKNOWN","OUTCOME_PRICE_COLUMN_MISSING","FAMILY_COVERAGE"],"future_buffer":"widened to at least the horizon on the outcome price request and reported as adjustments","library_sha256":"b4f10f55fd1ad4919be0eeca74b64dae955d46148fa027ec4a70ed9a01e17058","min_angles_env":"AI_RESEARCH_MIN_ANGLES (default 2)","min_families_env":"AI_RESEARCH_MIN_FAMILIES (0 = off)","replaces_version":"v1"}'::jsonb, 'v2', false
FROM public."Tool_Catalog" AS v1
WHERE v1.tool_name = 'check_research_feasibility' AND v1.version = 'v1';

