    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT v1.tool_name, v1.tool_family, v1.tool_type,
       'Run Python in one bundle group''s session (the helpers of run_python plus saniti.research_conditional, research_persistence, research_group_comparison, research_quantiles, research_temporal_dependency and research_custom). Record every angle of the group exactly once with its helper, starting from the angle''s example call in the session''s research view: request is the data request id string, each role an expression over that request''s columns, and the outcome {''forward_return'': ''<price column>''}, with ''request'': ''<request id>'' added when the price column is in another request of the angle''s contract (the backend computes it over the approved horizon; never a price level or a trailing return column). The thresholds, lags, buckets, groups and horizon come from the approved plan. Moving to another group completes the open one first. Read every dataset of the group through the saniti helpers.',
       '{"additionalProperties":false,"properties":{"bundle_group_id":{"description":"The bundle group whose session runs the code, e.g. g1.","type":"string"},"code":{"description":"Python for that group''s session.","type":"string"}},"required":["bundle_group_id","code"],"type":"object"}'::jsonb,
       v1.output_schema,
       v1.execution_type, v1.handler_name, v1.default_output_rows, v1.max_output_rows,
       v1.max_input_rows, v1.max_tickers, v1.max_date_range_days, v1.max_estimated_rows,
       v1.timeout_seconds, v1.max_output_bytes, v1.max_llm_result_rows,
       v1.max_llm_result_bytes, v1.max_llm_result_tokens,
       v1.requires_analytics_worker, v1.requires_feature_catalog, v1.requires_data_readiness,
       v1.tool_specific_limits || '{"forward_return_request":"S15 (2026-09-29): {''forward_return'': ''<price column>'', ''request'': ''<request id>''} reads the price of another request of the angle''s contract; a return outcome that is a price level is INVALID OUTCOME_NOT_APPROVED","replaces_version":"v1"}'::jsonb, 'v2', false
FROM public."Tool_Catalog" AS v1
WHERE v1.tool_name = 'run_research_code' AND v1.version = 'v1';

