SELECT v1.tool_name, v1.tool_family, v1.tool_type,
       'Complete the research run: the backend validates the open group (coverage, one recorded input per approved angle) and recomputes every angle''s statistics independently, then returns one backend finding per angle (SUPPORTED, PARTIALLY_SUPPORTED, INSUFFICIENT_EVIDENCE, INVALID or NOT_RUN, with its validation level), the angle completion counts and the research synthesis map. With finalize false it reports what is still missing; record those angles and call it again. finalize true accepts the result as it stands (unrecorded angles become NOT_RUN); while an approved angle is unrecorded the first finalize true is answered with the missing angles instead. Answer only from these findings.',
       '{"additionalProperties":false,"properties":{"finalize":{"description":"false: complete and report what is missing. true: accept the result as it stands; angles without a record and groups never run become NOT_RUN, INVALID findings stay INVALID.","type":"boolean"}},"required":["finalize"],"type":"object"}'::jsonb,
       '{"description":"The grouped result: one backend finding per approved angle (research_findings/v2), angle completion counts, the weakest validation level relied on and the research synthesis map; or INCOMPLETE with what is missing, including ANGLES_NOT_RECORDED for the first finalize while an approved angle is unrecorded.","properties":{"angle_completion":{},"angles_of_groups_not_run":{},"calculation_validation":{},"code":{},"groups":{},"groups_not_run":{},"missing_angle_ids":{},"next_action":{},"plan_id":{},"released_contents":{},"research_findings":{},"research_findings_version":{},"research_run_id":{},"research_synthesis_map":{},"status":{}},"type":"object"}'::jsonb,
       v1.execution_type, v1.handler_name, v1.default_output_rows, v1.max_output_rows,
       v1.max_input_rows, v1.max_tickers, v1.max_date_range_days, v1.max_estimated_rows,
       v1.timeout_seconds, v1.max_output_bytes, v1.max_llm_result_rows,
       v1.max_llm_result_bytes, v1.max_llm_result_tokens,
       v1.requires_analytics_worker, v1.requires_feature_catalog, v1.requires_data_readiness,
       v1.tool_specific_limits || '{"early_finalize":"M36 (2026-09-29): the first finalize true while an approved angle is unrecorded and at least two tool calls remain returns INCOMPLETE ANGLES_NOT_RECORDED; the second is accepted","replaces_version":"v1"}'::jsonb, 'v2', false
FROM public."Tool_Catalog" AS v1
WHERE v1.tool_name = 'complete_research_run' AND v1.version = 'v1';

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
VALUES
    ('get_research_library', 'DISCOVERY', 'RETRIEVAL', 'List the research methods a multi-angle Research Plan can use (the research library). Each method gives its family, the question it answers, its input roles, required and optional parameters with their rules, its data requirements (entity column, label, outcome, entities per date), the sample unit, the secondary checks, how to read the result and how it is misread, and an example question; plus the requirements every method shares. Choose each angle''s method and parameters from it before check_research_feasibility. It describes the methods; the backend computes them and sets each angle''s status.',
     '{"additionalProperties":false,"properties":{"method_ids":{"anyOf":[{"items":{"enum":["conditional_distribution","threshold_sensitivity","streak_persistence","regime_comparison","cohort_comparison","quantile_ranking","lead_lag","correlation_dependency"],"type":"string"},"type":"array"},{"type":"null"}],"description":"null for every method, or the methods to read."}},"required":["method_ids"],"type":"object"}'::jsonb, '{"description":"The research library: library_version, engine_version, library_sha256, the requirements every method shares, the decision rules reference and one entry per method (family, question shape, input roles, parameters, data requirements, sample unit, secondary checks, interpretation, misuse warning, example question).","properties":{"common_requirements":{},"decision_rules_ref":{},"engine_version":{},"library_sha256":{},"library_version":{},"method_count":{},"methods":{},"note":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, 40000, 8, 40000, NULL,
     false, false, false, '{"design":"MULTI_ANGLE_FIX_PLAN.md item 2 (C07)","feature_flag":"AI_ENABLE_MULTI_ANGLE_RESEARCH","handler":"app/tools/library.py (research_library_spec)","library_sha256":"b4f10f55fd1ad4919be0eeca74b64dae955d46148fa027ec4a70ed9a01e17058","plan_turn":"offered with the discovery tools in the Research Plan turns","registry_state":"Registered in market-ai-orc only when multi-angle research is active and AI_research_library, the sandbox capability and market-ai-orc''s app/research_library.py carry the same library_sha256 (else research_library_mismatch and multi-angle research stays inactive); is_active=false keeps it out of market-ai-backend tool lists.","runtime_service":"market-ai-orc","source_table":"public.\"AI_research_library\" (read once at startup by market_ai_catalog_reader)"}'::jsonb, 'v1', false);

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND NOT is_active AND (tool_name, version) IN (('check_research_feasibility', 'v2'), ('run_research_code', 'v2'), ('complete_research_run', 'v2'), ('get_research_library', 'v1'))) <> 4 THEN
        RAISE EXCEPTION 'Expected 4 inactive multi-angle fix tool registrations';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE version = 'v2'
          AND tool_specific_limits->>'replaces_version' = 'v1'
          AND tool_name IN ('check_research_feasibility', 'run_research_code', 'complete_research_run')) <> 3 THEN
        RAISE EXCEPTION 'Expected three v2 rows that copy their v1 limits';
    END IF;
    IF (SELECT input_schema->'properties'->'angles'->'items'->'required' ? 'design' FROM public."Tool_Catalog"
          WHERE tool_name = 'check_research_feasibility' AND version = 'v2') IS NOT TRUE THEN
        RAISE EXCEPTION 'check_research_feasibility v2 does not require each angle''s design';
    END IF;
    IF (SELECT version FROM public."Tool_Catalog" WHERE tool_name = 'check_research_feasibility'
          ORDER BY length(version) DESC, version DESC LIMIT 1) <> 'v2' THEN
        RAISE EXCEPTION 'check_research_feasibility v2 is not the latest version';
    END IF;
END;
$verify$;

COMMIT;
